UPDATE app_user
SET account_deletion_reservation_until =
      DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 1 HOUR)
WHERE id = #{id}
  AND account_deletion_reservation_owner = #{owner}
  AND account_deletion_reservation_until > UTC_TIMESTAMP(6)

UPDATE app_user
SET account_deletion_reserved_at = NULL,
    account_deletion_reservation_owner = NULL,
    account_deletion_reservation_until = NULL
WHERE id = #{id}
  AND account_deletion_reservation_owner = #{owner}

mapper.select:

SELECT EXISTS (
  SELECT 1
  FROM org_member om
  JOIN organization o ON o.id = om.org_id AND o.lifecycle_state = 'active'
  WHERE om.user_id = #{id}
    AND (
      EXISTS (
        SELECT 1 FROM org_member peer
        WHERE peer.org_id = om.org_id AND peer.user_id <> #{id}
      )
      OR EXISTS (
        SELECT 1
        FROM workspace_member peer
        JOIN workspace pw ON pw.id = peer.workspace_id AND pw.lifecycle_state = 'active'
        WHERE pw.org_id = om.org_id AND peer.user_id <> #{id}
      )
    )
  UNION ALL
  SELECT 1
  FROM workspace_member wm
  JOIN workspace w ON w.id = wm.workspace_id AND w.lifecycle_state = 'active'
  JOIN organization o ON o.id = w.org_id AND o.lifecycle_state = 'active'
  WHERE wm.user_id = #{id}
    AND wm.status = 'active'
    AND wm.role_id IS NULL
    AND wm.role IN ('admin', 'owner')
    AND (
      EXISTS (
        SELECT 1 FROM workspace_member peer
        WHERE peer.workspace_id = wm.workspace_id AND peer.user_id <> #{id}
      )
      OR EXISTS (
        SELECT 1 FROM org_member peer
        WHERE peer.org_id = w.org_id AND peer.user_id <> #{id}
      )
    )
  UNION ALL
  SELECT 1
  FROM workspace_member wm
  JOIN workspace w ON w.id = wm.workspace_id AND w.lifecycle_state = 'active'
  JOIN organization o ON o.id = w.org_id AND o.lifecycle_state = 'active'
  JOIN workspace_role_permission wrp ON wrp.workspace_role_id = wm.role_id
  WHERE wm.user_id = #{id}
    AND wm.status = 'active'
    AND wrp.permission IN (
      'AUDIT_READ', 'CAMPAIGN_MANAGE', 'CAMPAIGN_SEND', 'CONSENT_MANAGE',
      'CUSTOM_FIELD_MANAGE', 'DOCUMENT_MANAGE', 'MEMBER_MANAGE', 'PIPELINE_MANAGE',
      'PRODUCT_MANAGE', 'ROLE_MANAGE', 'RULE_MANAGE', 'SHARE_MANAGE',
      'TAG_MANAGE', 'WORKSPACE_SETTINGS'
    )
    AND (
      EXISTS (
        SELECT 1 FROM workspace_member peer
        WHERE peer.workspace_id = wm.workspace_id AND peer.user_id <> #{id}
      )
      OR EXISTS (
        SELECT 1 FROM org_member peer
        WHERE peer.org_id = w.org_id AND peer.user_id <> #{id}
      )
    )
)

mapper.update:
UPDATE app_user
username = #{username}, display_name = #{displayName}, email = #{email}, timezone = COALESCE(#{timezone}, timezone), password_hash = #{passwordHash},
WHERE id = #{id}

UPDATE app_user
SET last_login_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE app_user
SET epoch_restamp_session_primary_id = #{sessionPrimaryId},
    epoch_restamp_epoch = #{epoch}
WHERE id = #{id}

UPDATE app_user
SET password_hash = #{passwordHash}
WHERE id = #{id}

UPDATE app_user
SET email = #{email}
WHERE id = #{id}

UPDATE app_user
SET email_verified = TRUE
WHERE id = #{id}

UPDATE app_user
SET profile_picture_url = #{profilePictureUrl}
WHERE id = #{id} AND profile_picture_url <=> #{currentProfilePictureUrl}

UPDATE app_user
SET timezone = #{timezone}
WHERE id = #{id}

UPDATE app_user
SET locale = #{locale}
WHERE id = #{id}
